[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fresh Pantry — Discover Everyday Deliciousness</title>
<meta name="description" content="A neighborhood grocery store offering unique, high-quality food products at great prices.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700;800;900&family=Nunito+Sans:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
:root {
  --color-primary: #2D6A4F;
  --color-primary-light: #3d8b67;
  --color-primary-dark: #1e4a35;
  --color-accent: #F4A261;
  --color-accent-light: #f7b87b;
  --color-accent-dark: #e08a3e;
  --color-bg: #FEFAE0;
  --color-bg-light: #fffef5;
  --color-bg-dark: #f5efd0;
  --color-surface: #FFFFFF;
  --color-text: #1a1a1a;
  --color-text-secondary: #555555;
  --color-text-muted: #777777;
  --color-border: #e8dfc8;
  --color-success: #2D6A4F;
  --color-error: #c0392b;
  --font-heading: 'Nunito', sans-serif;
  --font-body: 'Nunito Sans', sans-serif;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.10);
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --max-width: 1200px;
  --transition: 200ms ease-out;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; height: auto; display: block; }

a { color: inherit; text-decoration: none; }

button { cursor: pointer; font-family: inherit; border: none; background: none; }

ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

.section { padding: 80px 0; }

.section--cream { background-color: var(--color-bg-dark); }

.section__label {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 8px;
}

.section__title {
  font-family: var(--font-heading);
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  color: var(--color-primary-dark);
  line-height: 1.2;
  margin-bottom: 12px;
}

.section__subtitle {
  font-size: 1.1rem;
  color: var(--color-text-secondary);
  max-width: 600px;
  line-height: 1.6;
}

/* ── HEADER ────────────────────────────────── */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  transition: box-shadow var(--transition);
}

.header--scrolled { box-shadow: var(--shadow-sm); }

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 68px;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--color-primary);
}

.header__logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-primary);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.header__logo-icon svg { width: 20px; height: 20px; color: #fff; }

.header__nav { display: flex; gap: 8px; }

.header__nav-link {
  font-family: var(--font-heading);
  font-size: 0.93rem;
  font-weight: 600;
  color: var(--color-text);
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  transition: background var(--transition), color var(--transition);
}

.header__nav-link:hover,
.header__nav-link:focus-visible {
  background: var(--color-bg-dark);
  color: var(--color-primary);
}

.header__nav-link:focus-visible { outline: 2px solid var(--color-primary); outline-offset: 2px; }

.header__menu-toggle {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
}

/* ── HERO ──────────────────────────────────── */
.hero {
  padding: 80px 0 60px;
  background: linear-gradient(170deg, #fffef9 0%, var(--color-bg) 40%, #f5efd0 100%);
}

.hero__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.hero__content { max-width: 540px; }

.hero__badge {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-accent-dark);
  background: rgba(244, 162, 97, 0.12);
  padding: 6px 16px;
  border-radius: 100px;
  margin-bottom: 20px;
}

.hero__title {
  font-family: var(--font-heading);
  font-size: clamp(2.2rem, 5vw, 3.5rem);
  font-weight: 900;
  color: var(--color-primary-dark);
  line-height: 1.1;
  margin-bottom: 16px;
}

.hero__title span { color: var(--color-accent); }

.hero__subtitle {
  font-size: 1.15rem;
  color: var(--color-text-secondary);
  line-height: 1.7;
  margin-bottom: 32px;
}

.hero__ctas { display: flex; gap: 14px; flex-wrap: wrap; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 0.95rem;
  font-weight: 700;
  padding: 14px 28px;
  border-radius: var(--radius-md);
  transition: transform var(--transition), box-shadow var(--transition), background var(--transition);
}

.btn:active { transform: scale(0.97); }

.btn--primary {
  background: var(--color-primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(45, 106, 79, 0.3);
}

.btn--primary:hover { background: var(--color-primary-light); box-shadow: 0 6px 20px rgba(45, 106, 79, 0.4); }

.btn--primary:focus-visible { outline: 2px solid var(--color-primary); outline-offset: 2px; }

.btn--outline {
  background: var(--color-surface);
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn--outline:hover { background: var(--color-primary); color: #fff; }

.btn--outline:focus-visible { outline: 2px solid var(--color-primary); outline-offset: 2px; }

.hero__visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero__image-wrapper {
  position: relative;
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.hero__image-wrapper img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero__floating-card {
  position: absolute;
  bottom: -16px;
  left: -20px;
  background: var(--color-surface);
  padding: 16px 20px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-heading);
}

.hero__floating-card-icon {
  width: 44px;
  height: 44px;
  background: rgba(45, 106, 79, 0.1);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.hero__floating-card-text { font-size: 0.88rem; font-weight: 700; color: var(--color-primary-dark); }

.hero__floating-card-sub { font-size: 0.75rem; color: var(--color-text-muted); font-weight: 500; }

/* ── FEATURED PRODUCTS CAROUSEL ────────────── */
.featured__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}

.featured__arrows {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.featured__arrow {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-surface);
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text);
  transition: all var(--transition);
}

.featured__arrow:hover {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: #fff;
}

.featured__arrow:focus-visible { outline: 2px solid var(--color-primary); outline-offset: 2px; }

.featured__arrow:disabled { opacity: 0.4; cursor: default; }
.featured__arrow:disabled:hover { background: var(--color-surface); border-color: var(--color-border); color: var(--color-text); }

.featured__track-outer {
  overflow: hidden;
  margin: 0 -24px;
  padding: 0 24px;
}

.featured__track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  padding: 8px 0 16px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.featured__track::-webkit-scrollbar { display: none; }

.product-card {
  flex: 0 0 260px;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  scroll-snap-align: start;
  transition: transform var(--transition), box-shadow var(--transition);
}

.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }

.product-card__image {
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
  background: #f0ebe0;
}

.product-card__body { padding: 18px; }

.product-card__name {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 4px;
  line-height: 1.3;
}

.product-card__desc {
  font-size: 0.85rem;
  color: var(--color-text-muted);
  line-height: 1.5;
  margin-bottom: 12px;
}

.product-card__price {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 800;
  color: var(--color-accent-dark);
}

/* ── BRAND HIGHLIGHTS ──────────────────────── */
.highlights {
  padding: 48px 0;
  background: var(--color-primary);
  color: #fff;
}

.highlights__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  text-align: center;
}

.highlight__number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 2.8rem);
  font-weight: 900;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: 8px;
}

.highlight__label {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.highlight__desc {
  font-size: 0.85rem;
  opacity: 0.75;
  line-height: 1.5;
}

/* ── SEASONAL PICKS ────────────────────────── */
.seasonal__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.seasonal-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
}

.seasonal-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }

.seasonal-card__image {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background: #f0ebe0;
}

.seasonal-card__body { padding: 18px; }

.seasonal-card__name {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 4px;
  line-height: 1.3;
}

.seasonal-card__desc {
  font-size: 0.85rem;
  color: var(--color-text-muted);
  line-height: 1.5;
  margin-bottom: 10px;
}

.seasonal-card__price {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--color-accent-dark);
}

/* ── CATEGORIES ────────────────────────────── */
.categories__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
}

.category-card {
  position: relative;
  aspect-ratio: 3/4;
  border-radius: var(--radius-lg);
  overflow: hidden;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
}

.category-card:hover { transform: scale(1.04); box-shadow: var(--shadow-md); }

.category-card:focus-visible { outline: 2px solid var(--color-primary); outline-offset: 2px; }

.category-card__bg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: #e8dfc8;
}

.category-card__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(30, 74, 53, 0.85) 0%, rgba(30, 74, 53, 0.2) 60%, transparent 100%);
  display: flex;
  align-items: flex-end;
  padding: 20px;
  transition: background var(--transition);
}

.category-card:hover .category-card__overlay { background: linear-gradient(to top, rgba(30, 74, 53, 0.9) 0%, rgba(30, 74, 53, 0.35) 60%, transparent 100%); }

.category-card__name {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 800;
  color: #fff;
  line-height: 1.2;
}

.category-card__desc {
  font-size: 0.8rem;
  color: rgba(255,255,255,0.8);
  margin-top: 4px;
  line-height: 1.4;
}

/* ── STORE LOCATOR ─────────────────────────── */
.locator__form {
  display: flex;
  gap: 12px;
  max-width: 520px;
  margin-top: 24px;
}

.locator__input {
  flex: 1;
  font-family: var(--font-body);
  font-size: 1rem;
  padding: 14px 18px;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  color: var(--color-text);
  transition: border-color var(--transition);
  min-width: 0;
}

.locator__input:focus { outline: none; border-color: var(--color-primary); }

.locator__input::placeholder { color: var(--color-text-muted); }

.locator__results {
  margin-top: 32px;
  display: none;
}

.locator__results--visible { display: block; }

.store-card {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 16px;
  align-items: center;
  background: var(--color-surface);
  padding: 20px 24px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  margin-bottom: 12px;
  transition: box-shadow var(--transition);
}

.store-card:hover { box-shadow: var(--shadow-md); }

.store-card__name {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-primary-dark);
}

.store-card__address { font-size: 0.88rem; color: var(--color-text-muted); margin-top: 2px; }

.store-card__hours {
  font-size: 0.85rem;
  color: var(--color-text-secondary);
  text-align: right;
  line-height: 1.4;
}

.store-card__distance {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--color-accent-dark);
  text-align: right;
  min-width: 60px;
}

.locator__empty {
  text-align: center;
  padding: 32px;
  color: var(--color-text-muted);
  display: none;
}

.locator__empty--visible { display: block; }

/* ── NEWSLETTER ────────────────────────────── */
.newsletter__inner {
  background: var(--color-primary);
  border-radius: var(--radius-xl);
  padding: 56px 48px;
  text-align: center;
  color: #fff;
}

.newsletter__title {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
  margin-bottom: 8px;
}

.newsletter__subtitle {
  font-size: 1.05rem;
  opacity: 0.85;
  margin-bottom: 28px;
  max-width: 520px;
  margin-left: auto;
  margin-right: auto;
}

.newsletter__form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
}

.newsletter__input {
  flex: 1;
  font-family: var(--font-body);
  font-size: 1rem;
  padding: 14px 18px;
  border: 2px solid transparent;
  border-radius: var(--radius-md);
  background: rgba(255,255,255,0.15);
  color: #fff;
  transition: border-color var(--transition), background var(--transition);
  min-width: 0;
}

.newsletter__input:focus { outline: none; border-color: var(--color-accent); background: rgba(255,255,255,0.2); }

.newsletter__input::placeholder { color: rgba(255,255,255,0.55); }

.newsletter__btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 700;
  padding: 14px 28px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  color: #fff;
  white-space: nowrap;
  transition: background var(--transition), transform var(--transition);
}

.newsletter__btn:hover { background: var(--color-accent-light); }
.newsletter__btn:active { transform: scale(0.97); }
.newsletter__btn:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }

.newsletter__confirmation {
  display: none;
  margin-top: 20px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: var(--color-accent);
}

.newsletter__confirmation--visible { display: block; }

/* ── FOOTER ────────────────────────────────── */
.footer {
  background: var(--color-primary-dark);
  color: rgba(255,255,255,0.8);
  padding: 56px 0 28px;
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 40px;
}

.footer__brand-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 10px;
}

.footer__brand-desc {
  font-size: 0.9rem;
  line-height: 1.7;
  max-width: 280px;
  opacity: 0.7;
}

.footer__heading {
  font-family: var(--font-heading);
  font-size: 0.88rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #fff;
  margin-bottom: 16px;
}

.footer__links { display: flex; flex-direction: column; gap: 10px; }

.footer__link {
  font-size: 0.9rem;
  opacity: 0.7;
  transition: opacity var(--transition), color var(--transition);
}

.footer__link:hover { opacity: 1; color: var(--color-accent); }

.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.12);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.85rem;
  opacity: 0.6;
  gap: 16px;
  flex-wrap: wrap;
}

/* ── RESPONSIVE ────────────────────────────── */
@media (max-width: 1024px) {
  .hero__inner { grid-template-columns: 1fr; gap: 40px; }
  .hero__visual { order: -1; }
  .hero__image-wrapper { max-width: 100%; aspect-ratio: 16/9; }
  .hero__floating-card { left: 8px; bottom: -12px; }
  .seasonal__grid { grid-template-columns: repeat(2, 1fr); }
  .categories__grid { grid-template-columns: repeat(3, 1fr); }
  .highlights__grid { grid-template-columns: repeat(2, 1fr); }
  .footer__grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .header__nav { display: none; }
  .header__nav--open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 68px;
    left: 0;
    right: 0;
    background: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    padding: 12px 24px;
    box-shadow: var(--shadow-md);
  }
  .header__menu-toggle { display: flex; }

  .section { padding: 56px 0; }
  .hero { padding: 40px 0 48px; }
  .hero__ctas { flex-direction: column; }
  .hero__ctas .btn { width: 100%; justify-content: center; }
  .hero__floating-card { display: none; }

  .featured__track-outer { margin: 0 -16px; padding: 0 16px; }
  .product-card { flex: 0 0 220px; }
  .seasonal__grid { grid-template-columns: repeat(2, 1fr); }
  .categories__grid { grid-template-columns: repeat(2, 1fr); }
  .highlights__grid { grid-template-columns: 1fr 1fr; gap: 24px; }

  .locator__form { flex-direction: column; }
  .store-card { grid-template-columns: 1fr; text-align: center; }
  .store-card__hours, .store-card__distance { text-align: center; }

  .newsletter__inner { padding: 36px 24px; }
  .newsletter__form { flex-direction: column; }
  .newsletter__btn { width: 100%; justify-content: center; }

  .footer__grid { grid-template-columns: 1fr; gap: 32px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .seasonal__grid { grid-template-columns: 1fr; }
  .categories__grid { grid-template-columns: 1fr 1fr; }
  .category-card { aspect-ratio: 1/1; }
  .highlights__grid { grid-template-columns: 1fr; }
